    /** @return array<string, string> key => name, for select inputs */
    public static function options(): array
    {
        return array_map(fn (array $p) => $p['name'], self::ALL);
    }

    public static function get(string $key): array
    {
        return self::ALL[$key] ?? self::ALL['other'];
    }

    /**
     * Accepts a full URL, "@username", "username" or (WhatsApp) a phone number,
     * and returns a full profile URL.
     */
    public static function normalize(string $platform, string $value): string
    {
        $value = trim($value);

        if (preg_match('#^https?://#i', $value)) {
            return $value;
        }
        if (preg_match('#^[\w.-]+\.[a-z]{2,}(/|$)#i', $value)) {
            return 'https://'.$value; // "instagram.com/me" or "mysite.dev"
        }

        $pattern = self::get($platform)['url'];
        $handle = ltrim($value, '@/');
        if ($platform === 'whatsapp') {
            $handle = preg_replace('/\D+/', '', $handle);
        }

        return $pattern ? str_replace('{h}', $handle, $pattern) : $value;
    }

    /** Short label for a URL: "@user" for social profiles, host/path otherwise. */
    public static function label(string $platform, string $url): string
    {
        $path = trim((string) parse_url($url, PHP_URL_PATH), '/');
        $last = $path === '' ? '' : basename($path);

        return match (true) {
            $platform === 'whatsapp' => '+'.ltrim($last, '+'),
            in_array($platform, ['website', 'other', 'stackoverflow', 'discord'], true), $last === '' =>
                preg_replace('#^(https?://)?(www\.)?#', '', rtrim($url, '/')),
            default => '@'.ltrim($last, '@'),
        };
    }
}
